from batch07 import *
start('stp','STP — role, zabezpieczenia i pętle','2.5',['https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst2960/software/release/12-2_53_se/configuration/guide/2960scg/swstpopt.html','https://www.cisco.com/c/en/us/support/docs/lan-switching/spanning-tree-protocol-stp-8021d/218321-configure-stp-with-loop-guard-and-bpdu-s.html'],True)
q('Najlepszy bridge ID','Który bridge ID wygrywa wybór roota STP, przy tej samej instancji?','Najniższy',['Najwyższy|STP preferuje niższy bridge ID.','Najkrótszy hostname|Hostname nie rozstrzyga wyboru.','Największa liczba portów|To nie kryterium wyboru root bridge.'],'Bridge ID uwzględnia priorytet i dalsze składniki identyfikujące most.')
q('Remis priorytetu','Dwa switche mają ten sam priorytet oraz extended system ID. Co rozstrzyga między nimi?','Niższy adres MAC mostu',['Wyższy adres IP SVI|SVI nie jest składnikiem tego wyboru.','Wyższy router ID OSPF|OSPF nie wybiera root bridge.','Więcej aktywnych VLAN-ów|Nie jest to kryterium bridge ID.'],'Przy równych wcześniejszych składnikach porównywany jest adres MAC.')
c('Dwa rooty VLAN','Ustaw jawnie priorytet 4096 dla VLAN 10 i 8192 dla VLAN 20 na tym switchu.','SW(config)# spanning-tree vlan 10 priority {{b0}}\nSW(config)# spanning-tree vlan 20 priority {{b1}}',['4096','8192'],'Priorytety są wielokrotnościami 4096. Rolę roota ocenia się względem pozostałych switchy.')
q('Root port','Jaką funkcję ma root port na switchu innym niż root, w danej instancji STP?','Najlepszą wybraną drogę do root bridge',['Zawsze połączenie z najwyższym numerem portu|Numer sam nie wyznacza najlepszej drogi.','Port do każdego hosta w VLAN-ie|To nie rola root port.','Automatycznie port administracyjnie shutdown|Root port zwykle przekazuje ruch po zbieżności.'],'Wybór uwzględnia koszt i kryteria rozstrzygające remisy.')
c('Root Guard i kontrola','Na kontrolowanym porcie w dół, gdzie nie może pojawić się lepszy root, ustaw Root Guard i pokaż inconsistent ports.','SW(config-if)# spanning-tree guard {{b0}}\nSW(config-if)# end\nSW# show spanning-tree {{b1}}',['root','inconsistentports'],'Root Guard może blokować port po odebraniu superior BPDU; nie powinien uniemożliwiać oczekiwanej drogi do roota.')
q('Root-inconsistent','Co typowo powoduje root-inconsistent przy aktywnym Root Guard?','Odebranie BPDU wskazującego lepszego roota',['Odebranie dowolnego pakietu DHCP|Root Guard dotyczy BPDU STP.','Samo wysłanie ARP przez klienta|ARP nie jest superior BPDU.','Przydzielenie adresu IPv6|Adresacja IP nie jest tą przyczyną.'],'Root Guard chroni umiejscowienie roota w zaprojektowanej części sieci.')
q('Powrót Root Guard','Co typowo następuje po ustaniu superior BPDU na porcie zablokowanym przez Root Guard?','Port może automatycznie wrócić po właściwym przeliczeniu STP',['Zawsze wymaga skasowania wszystkich VLAN-ów|To nie standardowy sposób przywracania.','Port na zawsze traci MAC|Root Guard nie usuwa fizycznego adresu urządzenia.','Switch zawsze restartuje się|To nie wymagane zachowanie.'],'Root-inconsistent różni się od trwałego administracyjnego shutdown.')
q('Loop Guard','Jakie ryzyko ogranicza Loop Guard na odpowiednim porcie STP?','Niepożądane przejście do forwarding po utracie oczekiwanych BPDU',['Utratę pakietów DNS na serwerze|To nie zakres Loop Guard.','Błędne hasło SSH|Nie jest funkcją uwierzytelniania.','Każdą zmianę MAC hosta|To nie Port Security.'],'Loop Guard reaguje na brak BPDU tam, gdzie ich odbiór jest oczekiwany, aby ograniczyć ryzyko pętli.')
c('Loop Guard i diagnostyka','Na odpowiednim łączu nie-edge włącz Loop Guard, pokaż inconsistent ports oraz STP VLAN 40.','SW(config-if)# spanning-tree guard {{b0}}\nSW(config-if)# end\nSW# show spanning-tree {{b1}}\nSW# show spanning-tree vlan {{b2}}',['loop','inconsistentports','40'],'Przed użyciem trzeba rozumieć rolę portu i oczekiwany kierunek BPDU.')
q('PortFast to nie brak STP','Czy PortFast oznacza całkowite wyłączenie STP na porcie?','Nie',['Tak, port przestaje być częścią STP|PortFast przyspiesza przejście portu edge, nie usuwa protokołu.','Tak, jeśli VLAN jest numerem parzystym|Numer VLAN-u nie wprowadza takiej zasady.','Tak, każde BPDU jest automatycznie filtrowane|PortFast nie jest tym samym co BPDU Filter.'],'PortFast stosuje się zgodnie z rolą brzegu; nie należy utożsamiać go z filtrowaniem BPDU.')
c('Port hosta z ochroną','Port G1/0/9 prowadzi wyłącznie do pojedynczego PC. Ustaw access, PortFast i interfejsowy BPDU Guard.','SW(config-if)# switchport mode {{b0}}\nSW(config-if)# spanning-tree {{b1}}\nSW(config-if)# spanning-tree bpduguard {{b2}}',['access','portfast','enable'],'BPDU Guard chroni założenie, że na porcie hosta nie powinien pojawić się most wysyłający BPDU.')
q('BPDU Guard a Root Guard','Które porównanie jest poprawne?','BPDU Guard reaguje na BPDU, Root Guard na superior BPDU zagrażające roli roota',['Oba działają wyłącznie na pakietach IP|Oba dotyczą kontroli STP.','Root Guard jest serwerem DHCP|Nie ma takiej roli.','BPDU Guard zawsze wybiera nowego roota|Typowa reakcja to blokada portu przez error-disable.'],'Oba mechanizmy mają różne zastosowania i warunki reakcji.')
q('RSTP learning','Port jest w stanie learning RSTP. Co dzieje się z typowym ruchem użytkowym?','MAC mogą być uczone, ale ramki użytkowe nie są jeszcze normalnie przekazywane',['Cały ruch użytkowy już swobodnie przechodzi|To odpowiada forwarding.','MAC nie mogą być nigdy uczone|Stan właśnie umożliwia naukę.','Wszystkie ramki są routowane między VLAN-ami|STP nie jest routingiem L3.'],'Stan portu rozdziela naukę źródeł od przekazywania ruchu.')
q('Zmiana kosztu','Obniżono koszt jednej drogi do roota. Czy gwarantuje to wybór nowego root port bez sprawdzenia całej topologii?','Nie',['Tak, każda obniżka zawsze wygrywa|Porównuje się całkowity koszt i inne kryteria.','Tak, koszt jest jedynym polem każdego BPDU|BPDU zawiera więcej informacji.','Nie, STP nigdy nie bierze kosztu pod uwagę|Koszt jest ważnym kryterium.'],'Wynik wynika z porównania całych reklamowanych ścieżek i reguł wyboru.')
c('Koszt i stan VLAN','Na G1/0/24 ustaw koszt STP 30 dla VLAN 60, pokaż tę instancję i porty niespójne.','SW(config-if)# spanning-tree vlan 60 cost {{b0}}\nSW(config-if)# end\nSW# show spanning-tree vlan {{b1}}\nSW# show spanning-tree {{b2}}',['30','60','inconsistentports'],'Jawny koszt wpływa na wybór ścieżki; wynik sprawdzaj operacyjnie zamiast zakładać konkretną rolę.')
q('Utrata BPDU jednostronnie','Na łączu przestały przychodzić BPDU, mimo że port nadal pokazuje up. Czy stan fizyczny up wyklucza problem kierunkowy?','Nie',['Tak, up gwarantuje działanie każdego kierunku protokołu|Stan linku nie dowodzi dostarczania wszystkich ramek.','Tak, STP nie potrzebuje BPDU po starcie|Utrzymanie informacji STP wymaga dalszej wymiany.','Tak, jeśli adres IP odpowiadał wczoraj|Dawny wynik nie potwierdza bieżącego stanu.'],'Diagnostyka powinna obejmować kierunkowość, BPDU i funkcje ochronne, nie tylko link up.')
c('Usunięta przyczyna BPDU Guard','Nieprawidłowy switch odłączono z portu hosta, przyczyna została zweryfikowana. W labie wykonaj shutdown/no shutdown, a potem pokaż status portów.','SW(config-if)# {{b0}}\nSW(config-if)# {{b1}}\nSW(config-if)# end\nSW# show interfaces {{b2}}',['shutdown','no shutdown','status'],'Podnoszenie portu przed usunięciem przyczyny prowadzi do ponownego naruszenia; nie wyłączaj ochrony tylko dla obejścia objawu.')
q('BPDU Filter ryzyko','Dlaczego nie należy bezrefleksyjnie włączać interfejsowego BPDU Filter na łączu między switchami?','Może odciąć wymianę STP potrzebną do zapobiegania pętli',['Ponieważ zawsze zmienia MAC routera|To nie jego funkcja.','Ponieważ zwiększa liczbę hostów DHCP|Nie przydziela adresów.','Ponieważ szyfruje każdy VLAN|Nie jest szyfrowaniem.'],'Filtrowanie BPDU może ukryć topologię przed STP; wymaga świadomego projektu i znajomości trybu działania.')
end()
